@page "/apply"
@using sv_6112018e542c4400bef9ce3925b3033f.Services
@rendermode InteractiveServer
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="apply-container">
    <h1>Job Application</h1>

    @* Step Indicator Bar *@
    <div class="step-indicator">
        @for (int i = 0; i < StepNames.Length; i++)
        {
            var stepIndex = i;
            var stepClass = GetStepClass(stepIndex);
            <div class="step @stepClass" @onclick="() => GoToStep(stepIndex)">
                <div class="step-circle">
                    @if (stepIndex < CurrentStep)
                    {
                        <span>&#10003;</span>
                    }
                    else
                    {
                        <span>@(stepIndex + 1)</span>
                    }
                </div>
                <div class="step-label">@StepNames[stepIndex]</div>
            </div>
            @if (i < StepNames.Length - 1)
            {
                <div class="step-connector @(stepIndex < CurrentStep ? "completed" : "")"></div>
            }
        }
    </div>

    @if (!string.IsNullOrEmpty(ErrorMessage))
    {
        <div class="error-message">@ErrorMessage</div>
    }

    @* Step Content *@
    @if (IsSubmitted)
    {
        <div class="confirmation">
            <h2>&#10003; Application Submitted!</h2>
            <p>Your application has been received. Your application ID is <strong>#@ApplicationId</strong>.</p>
            <p>Thank you for applying!</p>
        </div>
    }
    else
    {
        @switch (CurrentStep)
        {
            case 0:
                @RenderPersonalInfo();
                break;
            case 1:
                @RenderWorkHistory();
                break;
            case 2:
                @RenderReferences();
                break;
            case 3:
                @RenderCoverLetter();
                break;
            case 4:
                @RenderReview();
                break;
        }
    }
</div>

@* Step 1: Personal Info *@
@{ RenderFragment RenderPersonalInfo() =>
    @<div class="step-content">
        <h2>Personal Information</h2>
        <div class="form-group">
            <label for="fullName">Full Name *</label>
            <input id="fullName" type="text" @bind="FullName" placeholder="Enter your full name" />
        </div>
        <div class="form-group">
            <label for="email">Email *</label>
            <input id="email" type="email" @bind="Email" placeholder="Enter your email" />
        </div>
        <div class="form-group">
            <label for="phone">Phone *</label>
            <input id="phone" type="tel" @bind="Phone" placeholder="Enter your phone number" />
        </div>
        <div class="form-group">
            <label for="address">Address *</label>
            <input id="address" type="text" @bind="Address" placeholder="Enter your address" />
        </div>
        <div class="form-actions">
            <button class="btn-next" @onclick="NextFromPersonalInfo" disabled="@IsLoading">
                @if (IsLoading) { <span>Validating...</span> } else { <span>Next</span> }
            </button>
        </div>
    </div>;
}

@* Step 2: Work History *@
@{ RenderFragment RenderWorkHistory() =>
    @<div class="step-content">
        <h2>Work History</h2>
        @for (int i = 0; i < WorkEntries.Count; i++)
        {
            var index = i;
            <div class="work-entry-card">
                <div class="work-entry-header">
                    <h3>Position @(index + 1)</h3>
                    @if (WorkEntries.Count > 1)
                    {
                        <button class="btn-remove" @onclick="() => RemoveWorkEntry(index)">Remove</button>
                    }
                </div>
                <div class="form-group">
                    <label>Company Name *</label>
                    <input type="text" @bind="WorkEntries[index].Company" placeholder="Company name" />
                </div>
                <div class="form-group">
                    <label>Job Title *</label>
                    <input type="text" @bind="WorkEntries[index].Title" placeholder="Job title" />
                </div>
                <div class="form-row">
                    <div class="form-group">
                        <label>Start Date *</label>
                        <input type="date" @bind="WorkEntries[index].StartDate" />
                    </div>
                    <div class="form-group">
                        <label>End Date</label>
                        <input type="date" @bind="WorkEntries[index].EndDate" disabled="@WorkEntries[index].IsCurrent" />
                    </div>
                </div>
                <div class="form-group checkbox-group">
                    <input type="checkbox" id="current-@index" @bind="WorkEntries[index].IsCurrent" />
                    <label for="current-@index">I currently work here</label>
                </div>
                <div class="form-group">
                    <label>Description</label>
                    <textarea @bind="WorkEntries[index].Description" placeholder="Describe your responsibilities"></textarea>
                </div>
            </div>
        }
        <button class="btn-add" @onclick="AddWorkEntry">+ Add Another Position</button>
        <div class="form-actions">
            <button class="btn-back" @onclick="PreviousStep">Back</button>
            <button class="btn-next" @onclick="NextFromWorkHistory">Next</button>
        </div>
    </div>;
}

@* Step 3: References *@
@{ RenderFragment RenderReferences() =>
    @<div class="step-content">
        <h2>References</h2>
        @for (int i = 0; i < ReferenceEntries.Count; i++)
        {
            var index = i;
            <div class="reference-card">
                <div class="work-entry-header">
                    <h3>Reference @(index + 1)</h3>
                    @if (ReferenceEntries.Count > 2)
                    {
                        <button class="btn-remove" @onclick="() => RemoveReference(index)">Remove</button>
                    }
                </div>
                <div class="form-group">
                    <label>Name *</label>
                    <input type="text" @bind="ReferenceEntries[index].Name" placeholder="Reference name" />
                </div>
                <div class="form-group">
                    <label>Relationship *</label>
                    <input type="text" @bind="ReferenceEntries[index].Relationship" placeholder="e.g., Former Manager" />
                </div>
                <div class="form-group">
                    <label>Email *</label>
                    <input type="email" @bind="ReferenceEntries[index].Email" placeholder="Reference email" />
                </div>
                <div class="form-group">
                    <label>Phone *</label>
                    <input type="tel" @bind="ReferenceEntries[index].Phone" placeholder="Reference phone" />
                </div>
            </div>
        }
        @if (ReferenceEntries.Count < 3)
        {
            <button class="btn-add" @onclick="AddReference">+ Add Reference</button>
        }
        <div class="form-actions">
            <button class="btn-back" @onclick="PreviousStep">Back</button>
            <button class="btn-next" @onclick="NextFromReferences">Next</button>
        </div>
    </div>;
}

@* Step 4: Cover Letter *@
@{ RenderFragment RenderCoverLetter() =>
    @<div class="step-content">
        <h2>Cover Letter</h2>
        <div class="form-group">
            <label for="coverLetter">Write your cover letter</label>
            <textarea id="coverLetter" class="cover-letter-input" @bind="CoverLetterText" @bind:event="oninput"
                      placeholder="Tell us why you're a great fit for this position..." maxlength="2000"></textarea>
            <div class="char-count">@CoverLetterText.Length / 2000 characters</div>
        </div>
        <div class="form-actions">
            <button class="btn-back" @onclick="PreviousStep">Back</button>
            <button class="btn-next" @onclick="NextFromCoverLetter">Next</button>
        </div>
    </div>;
}

@* Step 5: Review & Submit *@
@{ RenderFragment RenderReview() =>
    @<div class="step-content">
        <h2>Review &amp; Submit</h2>

        <div class="review-section">
            <div class="review-header">
                <h3>Personal Information</h3>
                <button class="btn-edit" @onclick="() => GoToStep(0)">Edit</button>
            </div>
            <dl>
                <dt>Full Name</dt><dd>@FullName</dd>
                <dt>Email</dt><dd>@Email</dd>
                <dt>Phone</dt><dd>@Phone</dd>
                <dt>Address</dt><dd>@Address</dd>
            </dl>
        </div>

        <div class="review-section">
            <div class="review-header">
                <h3>Work History</h3>
                <button class="btn-edit" @onclick="() => GoToStep(1)">Edit</button>
            </div>
            @foreach (var entry in WorkEntries)
            {
                <div class="review-work-entry">
                    <strong>@entry.Title</strong> at <strong>@entry.Company</strong>
                    <br />
                    <span>@entry.StartDate.ToString("MMM yyyy") — @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy") ?? "N/A")</span>
                    @if (!string.IsNullOrWhiteSpace(entry.Description))
                    {
                        <p>@entry.Description</p>
                    }
                </div>
            }
        </div>

        <div class="review-section">
            <div class="review-header">
                <h3>References</h3>
                <button class="btn-edit" @onclick="() => GoToStep(2)">Edit</button>
            </div>
            @foreach (var reference in ReferenceEntries)
            {
                <div class="review-reference">
                    <strong>@reference.Name</strong> (@reference.Relationship)
                    <br />
                    <span>@reference.Email | @reference.Phone</span>
                </div>
            }
        </div>

        <div class="review-section">
            <div class="review-header">
                <h3>Cover Letter</h3>
                <button class="btn-edit" @onclick="() => GoToStep(3)">Edit</button>
            </div>
            <p class="review-cover-letter">@CoverLetterText</p>
        </div>

        <div class="form-actions">
            <button class="btn-back" @onclick="PreviousStep">Back</button>
            <button class="btn-submit" @onclick="SubmitApplication" disabled="@IsLoading">
                @if (IsLoading) { <span>Submitting...</span> } else { <span>Submit Application</span> }
            </button>
        </div>
    </div>;
}

@code {
    private static readonly string[] StepNames = { "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit" };

    private int CurrentStep { get; set; }
    private bool IsLoading { get; set; }
    private bool IsSubmitted { get; set; }
    private int ApplicationId { get; set; }
    private string? ErrorMessage { get; set; }

    // Step 1: Personal Info
    private string FullName { get; set; } = "";
    private string Email { get; set; } = "";
    private string Phone { get; set; } = "";
    private string Address { get; set; } = "";

    // Step 2: Work History
    private List<WorkEntryModel> WorkEntries { get; set; } = new() { new WorkEntryModel() };

    // Step 3: References
    private List<ReferenceModel> ReferenceEntries { get; set; } = new() { new ReferenceModel(), new ReferenceModel() };

    // Step 4: Cover Letter
    private string CoverLetterText { get; set; } = "";

    private string GetStepClass(int stepIndex)
    {
        if (stepIndex == CurrentStep) return "active";
        if (stepIndex < CurrentStep) return "completed";
        return "future";
    }

    private void GoToStep(int step)
    {
        if (step < CurrentStep)
        {
            ErrorMessage = null;
            CurrentStep = step;
        }
    }

    private void PreviousStep()
    {
        ErrorMessage = null;
        if (CurrentStep > 0) CurrentStep--;
    }

    // Step 1 validation and navigation
    private async Task NextFromPersonalInfo()
    {
        ErrorMessage = null;

        if (string.IsNullOrWhiteSpace(FullName) || string.IsNullOrWhiteSpace(Email) ||
            string.IsNullOrWhiteSpace(Phone) || string.IsNullOrWhiteSpace(Address))
        {
            ErrorMessage = "All fields are required.";
            return;
        }

        IsLoading = true;
        try
        {
            var isValidEmail = await ApplicationService.ValidateEmailAsync(Email);
            if (!isValidEmail)
            {
                ErrorMessage = "The email address is not valid.";
                return;
            }
            CurrentStep++;
        }
        finally
        {
            IsLoading = false;
        }
    }

    // Step 2 validation and navigation
    private void NextFromWorkHistory()
    {
        ErrorMessage = null;

        foreach (var entry in WorkEntries)
        {
            if (string.IsNullOrWhiteSpace(entry.Company) || string.IsNullOrWhiteSpace(entry.Title) ||
                entry.StartDate == default)
            {
                ErrorMessage = "Each work entry requires a company name, job title, and start date.";
                return;
            }
        }
        CurrentStep++;
    }

    // Step 3 validation and navigation
    private void NextFromReferences()
    {
        ErrorMessage = null;

        foreach (var reference in ReferenceEntries)
        {
            if (string.IsNullOrWhiteSpace(reference.Name) || string.IsNullOrWhiteSpace(reference.Relationship) ||
                string.IsNullOrWhiteSpace(reference.Email) || string.IsNullOrWhiteSpace(reference.Phone))
            {
                ErrorMessage = "All reference fields are required.";
                return;
            }
        }
        CurrentStep++;
    }

    // Step 4 navigation
    private void NextFromCoverLetter()
    {
        ErrorMessage = null;

        if (string.IsNullOrWhiteSpace(CoverLetterText))
        {
            ErrorMessage = "Please write a cover letter.";
            return;
        }
        CurrentStep++;
    }

    // Work History helpers
    private void AddWorkEntry() => WorkEntries.Add(new WorkEntryModel());

    private void RemoveWorkEntry(int index)
    {
        if (WorkEntries.Count > 1) WorkEntries.RemoveAt(index);
    }

    // Reference helpers
    private void AddReference()
    {
        if (ReferenceEntries.Count < 3) ReferenceEntries.Add(new ReferenceModel());
    }

    private void RemoveReference(int index)
    {
        if (ReferenceEntries.Count > 2) ReferenceEntries.RemoveAt(index);
    }

    // Submit
    private async Task SubmitApplication()
    {
        IsLoading = true;
        ErrorMessage = null;

        try
        {
            var personal = new PersonalInfo(FullName, Email, Phone, Address);
            var workHistory = new WorkHistory(WorkEntries.Select(e =>
                new WorkEntry(e.Company, e.Title, e.StartDate, e.IsCurrent ? null : e.EndDate, e.Description)).ToList());
            var references = ReferenceEntries.Select(r =>
                new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList();

            var application = new JobApplication(personal, workHistory, references, CoverLetterText);
            ApplicationId = await ApplicationService.SubmitApplicationAsync(application);
            IsSubmitted = true;
        }
        catch (Exception ex)
        {
            ErrorMessage = $"Submission failed: {ex.Message}";
        }
        finally
        {
            IsLoading = false;
        }
    }

    // View models for mutable form state
    private class WorkEntryModel
    {
        public string Company { get; set; } = "";
        public string Title { get; set; } = "";
        public DateTime StartDate { get; set; } = DateTime.Today;
        public DateTime? EndDate { get; set; }
        public bool IsCurrent { get; set; }
        public string Description { get; set; } = "";
    }

    private class ReferenceModel
    {
        public string Name { get; set; } = "";
        public string Relationship { get; set; } = "";
        public string Email { get; set; } = "";
        public string Phone { get; set; } = "";
    }
}

