+.apply-container {
+    max-width: 800px;
+    margin: 0 auto;
+    padding: 2rem;
+}
+
+.apply-container h1 {
+    text-align: center;
+    margin-bottom: 2rem;
+    color: #1a1a2e;
+}
+
+/* Step Indicator */
+.step-indicator {
+    display: flex;
+    align-items: center;
+    justify-content: center;
+    margin-bottom: 2rem;
+    padding: 1rem 0;
+}
+
+.step {
+    display: flex;
+    flex-direction: column;
+    align-items: center;
+    cursor: default;
+    min-width: 80px;
+}
+
+.step.completed {
+    cursor: pointer;
+}
+
+.step-circle {
+    width: 36px;
+    height: 36px;
+    border-radius: 50%;
+    display: flex;
+    align-items: center;
+    justify-content: center;
+    font-weight: bold;
+    font-size: 0.9rem;
+    border: 3px solid #ddd;
+    background: #fff;
+    color: #999;
+    transition: all 0.3s;
+}
+
+.step.active .step-circle {
+    border-color: #4361ee;
+    background: #4361ee;
+    color: #fff;
+}
+
+.step.completed .step-circle {
+    border-color: #2ecc71;
+    background: #2ecc71;
+    color: #fff;
+}
+
+.step.future .step-circle {
+    border-color: #ddd;
+    background: #f8f8f8;
+    color: #ccc;
+}
+
+.step-label {
+    margin-top: 0.5rem;
+    font-size: 0.75rem;
+    text-align: center;
+    color: #666;
+    white-space: nowrap;
+}
+
+.step.active .step-label {
+    color: #4361ee;
+    font-weight: 600;
+}
+
+.step.completed .step-label {
+    color: #2ecc71;
+}
+
+.step.future .step-label {
+    color: #ccc;
+}
+
+.step-connector {
+    flex: 1;
+    height: 3px;
+    background: #ddd;
+    margin: 0 0.25rem;
+    margin-bottom: 1.5rem;
+    transition: background 0.3s;
+}
+
+.step-connector.completed {
+    background: #2ecc71;
+}
+
+/* Form Content */
+.step-content {
+    background: #fff;
+    border: 1px solid #e0e0e0;
+    border-radius: 8px;
+    padding: 2rem;
+    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.05);
+}
+
+.step-content h2 {
+    margin-bottom: 1.5rem;
+    color: #1a1a2e;
+    border-bottom: 2px solid #4361ee;
+    padding-bottom: 0.5rem;
+}
+
+.form-group {
+    margin-bottom: 1.25rem;
+}
+
+.form-group label {
+    display: block;
+    margin-bottom: 0.4rem;
+    font-weight: 500;
+    color: #333;
+    font-size: 0.9rem;
+}
+
+.form-group input[type="text"],
+.form-group input[type="email"],
+.form-group input[type="tel"],
+.form-group input[type="date"],
+.form-group textarea {
+    width: 100%;
+    padding: 0.6rem 0.8rem;
+    border: 1px solid #ccc;
+    border-radius: 4px;
+    font-size: 0.95rem;
+    transition: border-color 0.2s;
+    box-sizing: border-box;
+}
+
+.form-group input:focus,
+.form-group textarea:focus {
+    outline: none;
+    border-color: #4361ee;
+    box-shadow: 0 0 0 2px rgba(67, 97, 238, 0.15);
+}
+
+.form-group textarea {
+    min-height: 100px;
+    resize: vertical;
+}
+
+.form-row {
+    display: flex;
+    gap: 1rem;
+}
+
+.form-row .form-group {
+    flex: 1;
+}
+
+.checkbox-group {
+    display: flex;
+    align-items: center;
+    gap: 0.5rem;
+}
+
+.checkbox-group input[type="checkbox"] {
+    width: auto;
+}
+
+.checkbox-group label {
+    display: inline;
+    margin-bottom: 0;
+    font-weight: normal;
+}
+
+/* Cards for entries */
+.work-entry-card,
+.reference-card {
+    border: 1px solid #e0e0e0;
+    border-radius: 6px;
+    padding: 1.25rem;
+    margin-bottom: 1rem;
+    background: #fafafa;
+}
+
+.work-entry-header {
+    display: flex;
+    justify-content: space-between;
+    align-items: center;
+    margin-bottom: 1rem;
+}
+
+.work-entry-header h3 {
+    margin: 0;
+    font-size: 1rem;
+    color: #444;
+}
+
+/* Buttons */
+.form-actions {
+    display: flex;
+    justify-content: space-between;
+    align-items: center;
+    margin-top: 2rem;
+    padding-top: 1rem;
+    border-top: 1px solid #eee;
+}
+
+.btn-next,
+.btn-submit {
+    padding: 0.7rem 1.8rem;
+    background: #4361ee;
+    color: #fff;
+    border: none;
+    border-radius: 4px;
+    font-size: 0.95rem;
+    font-weight: 500;
+    cursor: pointer;
+    transition: background 0.2s;
+    margin-left: auto;
+}
+
+.btn-next:hover,
+.btn-submit:hover {
+    background: #3451d1;
+}
+
+.btn-next:disabled,
+.btn-submit:disabled {
+    background: #a0a0a0;
+    cursor: not-allowed;
+}
+
+.btn-back {
+    padding: 0.7rem 1.8rem;
+    background: #fff;
+    color: #666;
+    border: 1px solid #ccc;
+    border-radius: 4px;
+    font-size: 0.95rem;
+    cursor: pointer;
+    transition: background 0.2s;
+}
+
+.btn-back:hover {
+    background: #f0f0f0;
+}
+
+.btn-add {
+    padding: 0.5rem 1rem;
+    background: #fff;
+    color: #4361ee;
+    border: 1px dashed #4361ee;
+    border-radius: 4px;
+    font-size: 0.9rem;
+    cursor: pointer;
+    margin-top: 0.5rem;
+    transition: background 0.2s;
+}
+
+.btn-add:hover {
+    background: #f0f4ff;
+}
+
+.btn-remove {
+    padding: 0.3rem 0.8rem;
+    background: #fff;
+    color: #e74c3c;
+    border: 1px solid #e74c3c;
+    border-radius: 4px;
+    font-size: 0.8rem;
+    cursor: pointer;
+    transition: background 0.2s;
+}
+
+.btn-remove:hover {
+    background: #fdf0f0;
+}
+
+.btn-edit {
+    padding: 0.3rem 0.8rem;
+    background: transparent;
+    color: #4361ee;
+    border: 1px solid #4361ee;
+    border-radius: 4px;
+    font-size: 0.8rem;
+    cursor: pointer;
+    text-decoration: none;
+}
+
+.btn-edit:hover {
+    background: #f0f4ff;
+}
+
+/* Cover Letter */
+.cover-letter-input {
+    min-height: 250px !important;
+    font-family: inherit;
+}
+
+.char-count {
+    text-align: right;
+    font-size: 0.85rem;
+    color: #888;
+    margin-top: 0.3rem;
+}
+
+/* Error Message */
+.error-message {
+    background: #fdf0f0;
+    border: 1px solid #e74c3c;
+    color: #c0392b;
+    padding: 0.75rem 1rem;
+    border-radius: 4px;
+    margin-bottom: 1rem;
+    font-size: 0.9rem;
+}
+
+/* Review Section */
+.review-section {
+    border: 1px solid #e0e0e0;
+    border-radius: 6px;
+    padding: 1.25rem;
+    margin-bottom: 1rem;
+    background: #fafafa;
+}
+
+.review-header {
+    display: flex;
+    justify-content: space-between;
+    align-items: center;
+    margin-bottom: 0.75rem;
+}
+
+.review-header h3 {
+    margin: 0;
+    font-size: 1rem;
+    color: #333;
+}
+
+.review-section dl {
+    display: grid;
+    grid-template-columns: auto 1fr;
+    gap: 0.4rem 1rem;
+    margin: 0;
+}
+
+.review-section dt {
+    font-weight: 500;
+    color: #555;
+}
+
+.review-section dd {
+    margin: 0;
+    color: #333;
+}
+
+.review-work-entry,
+.review-reference {
+    padding: 0.5rem 0;
+    border-bottom: 1px solid #eee;
+}
+
+.review-work-entry:last-child,
+.review-reference:last-child {
+    border-bottom: none;
+}
+
+.review-cover-letter {
+    white-space: pre-wrap;
+    background: #fff;
+    padding: 0.75rem;
+    border-radius: 4px;
+    border: 1px solid #eee;
+    margin: 0;
+}
+
+/* Confirmation */
+.confirmation {
+    text-align: center;
+    padding: 3rem;
+    background: #f0fff4;
+    border: 1px solid #2ecc71;
+    border-radius: 8px;
+}
+
+.confirmation h2 {
+    color: #2ecc71;
+    font-size: 1.5rem;
+}
+
+.btn-submit {
+    background: #2ecc71;
+}
+
+.btn-submit:hover {
+    background: #27ae60;
+}
+

